package spms.service;
import org.junit.jupiter.api.Test;import spms.model.*;import static org.junit.jupiter.api.Assertions.*;
class AuthorizationTest {@Test void rolesExposeOnlyPermittedModules(){User employee=new Employee(1,"sam","EMPLOYEE","E1");User hr=new HRManager(2,"hr","HR_MANAGER",null);User admin=new Admin(3,"admin","ADMIN",null);assertTrue(employee.canAccess("Attendance & Leave"));assertFalse(employee.canAccess("Administration"));assertTrue(hr.canAccess("Payroll Management"));assertFalse(hr.canAccess("Administration"));assertTrue(admin.canAccess("Administration"));}@Test void employeeCannotCreateEmployeeRecords(){SpmsService service=new SpmsService(new Employee(1,"sam","EMPLOYEE","E1"));assertThrows(SecurityException.class,()->service.addEmployee("E2","New Person","new@example.com","1234567","Engineering","Engineer","2026-01-01","1000"));}@Test void employeeWithoutLinkedProfileCannotListTheDirectory(){SpmsService service=new SpmsService(new Employee(3,"sam","EMPLOYEE",null));assertThrows(SecurityException.class,()->service.list("employees",""));}@Test void reversedLeaveDatesAreRejectedBeforePersistence(){SpmsService service=new SpmsService(new Employee(3,"sam","EMPLOYEE","SP001"));assertThrows(IllegalArgumentException.class,()->service.applyLeave("SP999","2026-05-12","2026-05-11","Annual","Test"));}}
